#[derive(Debug, thiserror::Error)]
pub enum CpError {
    /// Permission denied.
    #[error("{}", translate!("cp-error-cannot-open-for-reading", "source" => .0.quote()))]
    CannotOpenForReading(PathBuf),

    /// Simple [`io::Error`] wrapper
    #[error("{0}")]
    IoErr(#[from] io::Error),

    /// Wrapper for [`io::Error`] with path context
    #[error("{1}: {0}")]
    IoErrContext(io::Error, String),

    /// General copy error
    #[error("{0}")]
    Error(String),

    /// The SELinux security context of the destination could not be
    /// preserved; unlike other attribute failures, this one empties the
    /// destination file.
    #[error("{0}")]
    SelinuxContext(String),

    /// Same as [`CpError::SelinuxContext`], but keeping the errno so that an
    /// ENOTSUP on a fixed-context mount can still be silenced.
    #[error("{1}: {0}")]
    SelinuxContextIoErr(io::Error, String),

    /// Represents the state when a non-fatal error has occurred
    /// and not all files were copied.
    #[error("{}", translate!("cp-error-not-all-files-copied"))]
    NotAllFilesCopied,

    /// Simple [`walkdir::Error`] wrapper
    #[error("{0}")]
    WalkDirErr(#[from] walkdir::Error),

    /// Simple [`StripPrefixError`] wrapper
    #[error(transparent)]
    StripPrefixError(#[from] StripPrefixError),

    /// Result of a skipped file
    /// Currently happens when "no" is selected in interactive mode or when
    /// `no-clobber` flag is set and destination is already present.
    /// `exit with error` is used to determine which exit code should be returned.
    #[error("Skipped copying file (exit with error = {0})")]
    Skipped(bool),

    /// Invalid argument error
    #[error("{0}")]
    InvalidArgument(String),

    /// All standard options are included as an implementation
    /// path, but those that are not implemented yet should return
    /// a `NotImplemented` error.
    #[error("{}", translate!("cp-error-option-not-implemented", "option" => 0))]
    NotImplemented(String),

    /// Invalid arguments to backup
    #[error(transparent)]
    Backup(#[from] BackupError),

    #[error("{}", translate!("cp-error-not-a-directory", "path" => .0.quote()))]
    NotADirectory(PathBuf),

    /// A directory would have to replace something that is not one.
    #[error("{}", translate!("cp-error-cannot-overwrite-non-directory-with-directory", "dest" => .0.quote(), "source" => .1.quote()))]
    CannotOverwriteNonDirectory(PathBuf, PathBuf),
}

